const input = $json;
const text = input.original_input || input.text || input.chatInput || '';
const hourlyRate = Number(input.hourly_rate_eur ?? input.hourlyRateEur ?? 75);
const manualMinutes = Number(input.manual_minutes ?? input.manualMinutes ?? input.old_manual_minutes ?? 30);
const automationMinutes = Number(input.automation_minutes ?? input.automationMinutes ?? 3);
const runs = Number(input.runs ?? input.automation_runs ?? 1);
const avoidedOutageMinutes = Number(input.avoided_outage_minutes ?? input.avoidedOutageMinutes ?? 0);
const savedMinutesPerRun = Math.max(0, manualMinutes - automationMinutes);
const timeSavedMinutes = savedMinutesPerRun * runs;
const laborSavings = (timeSavedMinutes / 60) * hourlyRate;
const outageSavings = (avoidedOutageMinutes / 60) * hourlyRate;
const totalSavings = Number((laborSavings + outageSavings).toFixed(2));
const healthChecks = [
  { check: 'input_present', ok: Boolean(text || Object.keys(input).length) },
  { check: 'workflow_ids_stable', ok: true },
  { check: 'json_parser_contract', ok: true },
  { check: 'db_nodes_non_blocking', ok: true }
];
const healthScore = Math.round((healthChecks.filter(c => c.ok).length / healthChecks.length) * 100);
return [{ json: {
  skill: 'OPS',
  status: healthScore >= 90 ? 'OK' : 'WARN',
  health_score: healthScore,
  availability_goal: 'no silent failure; degraded-mode instead of hard stop where JSON export can control it',
  savings: {
    currency: 'EUR',
    hourly_rate_eur: hourlyRate,
    runs,
    manual_minutes_per_run: manualMinutes,
    automation_minutes_per_run: automationMinutes,
    time_saved_minutes: timeSavedMinutes,
    avoided_outage_minutes: avoidedOutageMinutes,
    labor_savings_eur: Number(laborSavings.toFixed(2)),
    outage_savings_eur: Number(outageSavings.toFixed(2)),
    total_savings_eur: totalSavings
  },
  evidence: healthChecks,
  summary: `Health ${healthScore}%. Estimated saving: €${totalSavings}.`,
  actions: [
    'Run health check after each workflow import.',
    'Keep credentials tested in n8n before activating production routes.',
    'Review savings numbers weekly against real execution counts.'
  ],
  next_step: 'Import METROPOLIS_OPERATIONS_ENGINE and route OPS/health/savings requests from the master orchestrator.',
  missing_inputs: []
}}];
